using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public class Solution
{
    public static bool HasSubpattern(string s)
    {
        if (s.Length <= 1)
            return false;

        // Create a regex pattern to match repeated substring
        string pattern = @"\b(.{1})\1+\b";
        MatchCollection matches = Regex.Matches(s, pattern);

        int minRepeatLength = s.Length / 2;
        int maxRepeatLength = s.Length / 2 + 1;

        foreach (Match match in matches)
        {
            int length = match.Length;

            if (length >= minRepeatLength && length < maxRepeatLength)
                return true;
        }

        return false;
    }
}
